window.TerraMapTools = (() => {
  const {el,field,error}=TerraUI;
  let mode='map',coordinateDirty=false,interestActive=false,interestPoints=[],interestLayer=null,segments=[];
  const searchArea=el('button',{hidden:true},'Buscar nesta área'),interestButton=el('button',{},'Desenhar área de interesse'),finish=el('button',{class:'primary',hidden:true},'Concluir área'),undo=el('button',{hidden:true},'Desfazer'),cancel=el('button',{hidden:true},'Cancelar'),save=el('button',{hidden:true,onclick:()=>TerraFilters.saveCurrent()},'Salvar esta área');
  const actions=el('div',{class:'map-search-actions'},searchArea,interestButton,finish,undo,cancel,save);document.querySelector('.map-wrap').append(actions);
  function currentBounds(){const b=map.getBounds();return {west:Math.max(-180,b.getWest()),east:Math.min(180,b.getEast()),south:Math.max(-85,b.getSouth()),north:Math.min(85,b.getNorth())};}
  searchArea.onclick=()=>{if(drawing||interestActive)return;TerraFilters.setArea({bounds:currentBounds()},'Área visível do mapa');searchArea.hidden=true;};
  map.on('moveend',()=>{searchArea.hidden=drawing||interestActive;});
  function displayInterest(geometry){if(interestLayer)interestLayer.remove();interestLayer=null;if(geometry)interestLayer=L.geoJSON(geometry,{style:{color:'#366aab',weight:3,dashArray:'7 5',fillOpacity:.07},interactive:false}).addTo(map);save.hidden=!geometry;}
  function drawInterest(){if(interestLayer)interestLayer.remove();interestLayer=interestPoints.length?(interestPoints.length>=3?L.polygon(interestPoints,{color:'#366aab',dashArray:'7 5',fillOpacity:.1,interactive:false}):L.polyline(interestPoints,{color:'#366aab',interactive:false})).addTo(map):null;finish.textContent='Concluir área ('+interestPoints.length+' pontos)';}
  function cancelInterest(){interestActive=false;interestPoints=[];finish.hidden=undo.hidden=cancel.hidden=true;interestButton.hidden=false;map.getContainer().style.cursor='';displayInterest(TerraFilters.get().polygon || null);}
  interestButton.onclick=()=>{if(drawing)return toast('Conclua a edição antes de desenhar uma área de busca.');interestActive=true;interestPoints=[];displayInterest(null);finish.hidden=undo.hidden=cancel.hidden=false;interestButton.hidden=searchArea.hidden=save.hidden=true;map.getContainer().style.cursor='crosshair';toast('Toque nos limites da região desejada e depois em Concluir área.');};
  cancel.onclick=cancelInterest;undo.onclick=()=>{interestPoints.pop();drawInterest();};
  map.on('click',event=>{if(!interestActive||drawing)return;if(interestPoints.length>=200)return toast('Use no máximo 200 vértices.');interestPoints.push(event.latlng);drawInterest();});
  finish.onclick=()=>{try{const geometry=TerraGeometry.polygon(interestPoints.map(p=>[p.lng,p.lat]));cancelInterest();TerraFilters.setArea({polygon:geometry},'Terrenos na área desenhada');displayInterest(geometry);}catch(exception){toast(exception.message);}};

  const method=el('select',{id:'boundary-method'},new Option('Desenhar no mapa','map'),new Option('Inserir coordenadas','coordinates'),new Option('Importar arquivo','import'));
  const rows=el('tbody'),coordinates=el('div',{id:'coordinate-editor',hidden:true},el('p',{class:'small'},'Latitude e longitude WGS84, em graus decimais. Ex.: −21.76245, −43.34891.'),el('div',{class:'coordinate-scroll'},el('table',{class:'coordinate-table'},el('thead',{},el('tr',{},['Vértice','Latitude','Longitude','Distância ao próximo',''].map(x=>el('th',{},x)))),rows)));
  const add=el('button',{type:'button'},'+ Adicionar vértice'),center=el('button',{type:'button'},'Centralizar desenho'),coordinateMessage=el('p',{class:'small',role:'status'});coordinates.append(add,center,coordinateMessage);
  center.onclick=()=>{if(points.length)map.fitBounds(points,{padding:[30,30],maxZoom:18});else toast('Preencha as coordenadas para localizar o desenho.');};
  const file=el('input',{type:'file',accept:'.geojson,.json,.kml,.kmz'}),importMessage=el('p',{role:'status',class:'small'}),importer=el('div',{hidden:true},field('Arquivo do perímetro',file),el('p',{class:'small'},'GeoJSON, JSON, KML ou KMZ, até 5 MB. Um polígono sem buracos, com 3 a 200 vértices.'),importMessage);
  const container=el('div',{class:'boundary-tools'},field('Como deseja informar os limites?',method),coordinates,importer);$('editor').querySelector('.measure').before(container);
  function replacePoints(geometry){points=geometry.coordinates[0].slice(0,-1).map(([lng,lat])=>L.latLng(lat,lng));updateDraw();map.fitBounds(points,{padding:[30,30],maxZoom:18});}
  function parseRows(){return [...rows.children].map(row=>{const inputs=row.querySelectorAll('input');if([...inputs].some(input=>input.value.trim()===''))throw new Error('Preencha latitude e longitude de todos os vértices.');const lat=Number(inputs[0].value.trim().replace(',','.')),lng=Number(inputs[1].value.trim().replace(',','.'));if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>85||Math.abs(lng)>180)throw new Error('Revise as coordenadas. Latitude: −85 a 85. Longitude: −180 a 180.');return [lng,lat];});}
  function refreshRows(){rows.replaceChildren();points.forEach(p=>addRow(p.lat,p.lng));if(!points.length)for(let i=0;i<3;i++)addRow();coordinateDirty=false;coordinateMessage.textContent='';updateDistances();}
  function updateDistances(){const items=[...rows.children];items.forEach((row,i)=>{row.firstChild.textContent=i+1;const cell=row.querySelector('.vertex-distance');cell.textContent='—';try{const vs=parseRows();if(vs.length>1){const p=vs[i],q=vs[(i+1)%vs.length];cell.textContent=num(map.distance([p[1],p[0]],[q[1],q[0]]))+' m';}}catch(_){}});}
  function coordinatesChanged(){if(saving)return;coordinateDirty=true;try{
    const vertices=parseRows();if(vertices.length<3){coordinateMessage.textContent='Adicione pelo menos 3 vértices.';return;}
    const geometry=TerraGeometry.polygon(vertices);points=geometry.coordinates[0].slice(0,-1).map(([lng,lat])=>L.latLng(lat,lng));updateDraw();coordinateMessage.textContent='Desenho atualizado. Confira a posição no mapa.';coordinateDirty=false;
  }catch(exception){coordinateMessage.textContent=exception.message+' O último desenho válido foi mantido.';}updateDistances();}
  function addRow(lat='',lng=''){const a=el('input',{type:'text',inputMode:'decimal',value:String(lat),'aria-label':'Latitude',maxLength:20}),b=el('input',{type:'text',inputMode:'decimal',value:String(lng),'aria-label':'Longitude',maxLength:20}),remove=el('button',{type:'button','aria-label':'Remover vértice'},'×'),row=el('tr',{},el('td',{},String(rows.children.length+1)),el('td',{},a),el('td',{},b),el('td',{class:'vertex-distance'},'—'),el('td',{},remove));a.oninput=b.oninput=coordinatesChanged;remove.onclick=()=>{if(!saving){row.remove();coordinatesChanged();}};rows.append(row);}
  add.onclick=()=>{if(saving)return;if(rows.children.length>=200)return toast('Use no máximo 200 vértices.');addRow();coordinateDirty=true;coordinateMessage.textContent='Preencha o novo vértice antes de salvar.';};
  method.onchange=()=>{if(saving){method.value=mode;return;}mode=method.value;coordinates.hidden=mode!=='coordinates';importer.hidden=mode!=='import';if(mode==='coordinates')refreshRows();$('undo').disabled=$('clear').disabled=mode!=='map';map.getContainer().style.cursor=mode==='map'?'crosshair':'';};
  file.onchange=async()=>{if(saving||!file.files[0])return;const targetId=editId;file.disabled=true;method.disabled=true;importMessage.textContent='Lendo e validando o perímetro…';try{const geometry=await TerraGeometry.read(file.files[0]);if(!drawing||editId!==targetId)return;replacePoints(geometry);coordinateDirty=false;importMessage.textContent='Arquivo importado com sucesso. Área: '+num(currentArea)+' m². '+$('perimeter').textContent+'.';}catch(exception){importMessage.textContent=exception.message;}finally{file.value='';file.disabled=false;method.disabled=false;}};
  function validateEditor(){if(mode==='coordinates'){const geometry=TerraGeometry.polygon(parseRows());if(coordinateDirty)replacePoints(geometry);}if(file.disabled)throw new Error('Aguarde a conclusão da importação.');TerraGeometry.polygon(points.map(p=>[p.lng,p.lat]));}
  function drawUpdated(vertices){segments.forEach(layer=>layer.remove());segments=[];if(!drawing||vertices.length<2)return;vertices.forEach((p,i)=>{if(i===vertices.length-1&&vertices.length<3)return;const q=vertices[(i+1)%vertices.length];if(vertices.length<=30)segments.push(L.tooltip({permanent:true,direction:'center',className:'segment-distance',interactive:false}).setLatLng([(p.lat+q.lat)/2,(p.lng+q.lng)/2]).setContent(num(map.distance(p,q))+' m').addTo(map));});}
  document.addEventListener('terra:editstart',()=>{cancelInterest();actions.hidden=true;mode='map';method.value=mode;coordinates.hidden=importer.hidden=true;coordinateDirty=false;importMessage.textContent='';$('undo').disabled=$('clear').disabled=false;});
  document.addEventListener('terra:editstop',()=>{actions.hidden=false;drawUpdated([]);});

  // Draggable mobile list. The map remains visible above the sheet.
  const handle=el('button',{id:'mobile-sheet-handle','aria-label':'Arraste para ajustar a lista ou toque para recolher'},el('span',{class:'drag-pill'}),el('span',{},'Terrenos no mapa'));
  $('sidebar').prepend(handle);handle.onclick=()=>{document.body.classList.remove('show-list');$('sidebar').style.height='';$('mobile-toggle').textContent='Ver lista de terrenos';};
  let drag=null,moved=false;
  handle.onpointerdown=event=>{drag={y:event.clientY,height:$('sidebar').getBoundingClientRect().height};moved=false;handle.setPointerCapture(event.pointerId);};
  handle.onpointermove=event=>{if(!drag)return;const delta=drag.y-event.clientY;if(Math.abs(delta)>5)moved=true;const mainHeight=document.querySelector('main').clientHeight;$('sidebar').style.height=Math.max(mainHeight*.25,Math.min(mainHeight*.9,drag.height+delta))+'px';};
  handle.onpointerup=()=>{drag=null;};
  handle.addEventListener('click',event=>{if(moved){event.stopImmediatePropagation();event.preventDefault();moved=false;}},true);
  return {displayInterest,cancelInterest,validateEditor,drawUpdated,canMapDraw:()=>mode==='map'&&!interestActive};
})();
